import java.util.Scanner;

class Cat {
    String name;
    int fish;

    void eat(int n) {
        fish = fish + n;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String who1 = sc.next();
        int a = sc.nextInt();
        int b = sc.nextInt();
        String who2 = sc.next();
        int n = sc.nextInt();

        Cat c1 = new Cat();
        c1.name = who1;
        Cat c2 = new Cat();
        c2.name = who2;

        c1.eat(a);
        c1.eat(b);
        c2.eat(n);

        System.out.println(c1.name + " 一共吃了 " + c1.fish + " 条");
        System.out.println(c2.name + " 一共吃了 " + c2.fish + " 条");
    }
}

